// Characterization tests: pin the HTTP behaviour clients see today, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 2.5, C: 101, D: 50 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, json, string id, echoed items, total', async () => {
  const items = [{ sku: 'A', qty: 3 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order, { id: order.id, items, total: 30 })
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums multiple items', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 4 }] })).json()
  assert.equal(order.total, 20)
})

test('total is floored to a whole number', async () => {
  const order = await (await post({ items: [{ sku: 'B', qty: 3 }] })).json() // 7.5
  assert.equal(order.total, 7)
})

test('no discount at exactly 100', async () => {
  const order = await (await post({ items: [{ sku: 'D', qty: 2 }] })).json()
  assert.equal(order.total, 100)
})

test('10% discount above 100, then floored', async () => {
  const order = await (await post({ items: [{ sku: 'C', qty: 1 }] })).json() // 90.9
  assert.equal(order.total, 90)
  const big = await (await post({ items: [{ sku: 'D', qty: 4 }] })).json() // 200 -> 180
  assert.equal(big.total, 180)
})

test('POST /orders validation errors return 400 {error}', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }, { items: null }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders with malformed JSON returns 400', async () => {
  const res = await post(undefined, '{nope')
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('POST /orders with empty body returns 400', async () => {
  const res = await post(undefined, '')
  assert.equal(res.status, 400)
})

test('rejected orders are not stored and do not consume ids', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  await post({ items: [] })
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 2 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 (not 404) with {error: "not found"}', async () => {
  const res = await fetch(`${base}/orders/999999`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 {error: "no route"}', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/orders'], ['GET', '/orders/1/x'],
    ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/other']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query strings are ignored when routing', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}?x=1`)
  assert.deepEqual(await res.json(), created)
})
